def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    seen = set()
    for r in range(h-2):
        for c in range(w-2):
            color = grid[r][c]
            if color == 0 or (r,c,color) in seen:
                continue
            if all(grid[y][x] == color for y in range(r,r+3) for x in range(c,c+3)):
                blocks.append((r+1,c+1,color))
                seen.add((r,c,color))
    lines = []
    for r,c,color in blocks:
        lines.append(('row',r,color))
        lines.append(('col',c,color))
    for r in range(h):
        for c in range(w):
            colors = {color for axis,pos,color in lines if (axis == 'row' and pos == r) or (axis == 'col' and pos == c)}
            if len(colors) > 1:
                out[r][c] = 0
            elif colors:
                out[r][c] = next(iter(colors))
    return out
